insert into products (category_id, slug, name, description, price_cents, gender, images, colors, sizes, is_featured) values ((select id from categories where slug='tops'), 'oversized-cotton-tee', 'Oversized Cotton Tee', 'Heavyweight 240gsm cotton jersey with a boxy cut and dropped shoulder. Garment washed for softness. Cut roomy; size down for a closer fit.', 4800, 'unisex', array['https://picsum.photos/seed/oversized-cotton-tee-1/900/1125','https://picsum.photos/seed/oversized-cotton-tee-2/900/1125','https://picsum.photos/seed/oversized-cotton-tee-3/900/1125'], '[{"name":"Off White","hex":"#f2f0ea"},{"name":"Black","hex":"#1a1a1a"}]'::jsonb, array['S','M','L','XL'], true);
insert into products (category_id, slug, name, description, price_cents, gender, images, colors, sizes, is_featured) values ((select id from categories where slug='tops'), 'merino-crewneck', 'Merino Crewneck', 'Fine-gauge merino wool knit that regulates temperature and resists odor. Ribbed collar, cuffs and hem.', 12800, 'men', array['https://picsum.photos/seed/merino-crewneck-1/900/1125','https://picsum.photos/seed/merino-crewneck-2/900/1125','https://picsum.photos/seed/merino-crewneck-3/900/1125'], '[{"name":"Charcoal","hex":"#3a3d40"},{"name":"Oat","hex":"#d8cdb8"}]'::jsonb, array['S','M','L','XL'], false);
insert into products (category_id, slug, name, description, price_cents, gender, images, colors, sizes, is_featured) values ((select id from categories where slug='tops'), 'linen-shirt', 'Relaxed Linen Shirt', 'European linen shirt with mother-of-pearl buttons and a relaxed, easy drape. Softens with every wash.', 9800, 'women', array['https://picsum.photos/seed/linen-shirt-1/900/1125','https://picsum.photos/seed/linen-shirt-2/900/1125','https://picsum.photos/seed/linen-shirt-3/900/1125'], '[{"name":"White","hex":"#fafafa"},{"name":"Sage","hex":"#9aa88f"}]'::jsonb, array['XS','S','M','L'], false);
